/**
 * sample.js — a small demo photo embedded as a data-URI.
 *
 * Why embedded? Images loaded from file:// can "taint" a canvas in some browsers,
 * which would block pixel processing. A data-URI is always same-origin and safe.
 * Used only by the "Try sample photo" button.  (Source image: assets/sample/sample-lake.jpg)
 */
window.CMJ = window.CMJ || {};
CMJ.sampleDataUri = 'data:image/jpeg;base64,';
